/bin/bash -lc "apply_patch <<'PATCH'
*** Begin Patch
*** Update File: Task.v
@@
-  intros fuel v H. destruct fuel; simpl in H;
-    destruct H as [_ [_ [[n ->] [Hne _]]]].
+  intros fuel v H. destruct fuel; simpl in H;
+    destruct H as [_ [_ [[[n Heq] Hne] _]]];
+    exists n; split; [exact Heq|];
+    subst v; simpl in Hne; intro Hzero; subst n;
+    apply Hne; exists (tm_int 0%Z);
+    repeat split; constructor.
*** End Patch
PATCH
coqc Task.v"

